function ChartOfAccountsWorkspace({branch}:{branch:string}){
 const [ledgers,setLedgers]=useState<CoaLedger[]>(coaSeed),[query,setQuery]=useState(""),[filter,setFilter]=useState("All"),[scope,setScope]=useState("All"),[modal,setModal]=useState(false),[notice,setNotice]=useState("");
 const [form,setForm]=useState({code:"",name:"",type:"Asset",group:"Current Assets",parent:"Current Assets",opening:"0",side:"Debit",scope:"All branches"});
 const types=["All","Asset","Liability","Equity","Income","Expense"];
 const shown=ledgers.filter(x=>(filter==="All"||x.type===filter)&&(scope==="All"||x.scope===scope)&&`${x.code} ${x.name} ${x.group} ${x.parent}`.toLowerCase().includes(query.toLowerCase()));
 const count=(t:string)=>ledgers.filter(x=>x.type===t).length;
 const total=(t:string)=>ledgers.filter(x=>x.type===t).reduce((n,x)=>n+x.opening,0);
 const save=()=>{if(!form.code.trim()||!form.name.trim()){setNotice("Account code and ledger name are required.");return;}if(ledgers.some(x=>x.code===form.code.trim())){setNotice("Account code already exists. Use a unique code.");return;}setLedgers([{...form,code:form.code.trim(),name:form.name.trim(),opening:Number(form.opening)||0,side:form.side as "Debit"|"Credit"},...ledgers]);setModal(false);setNotice("Ledger added to this demo session. It resets when you refresh.");setForm({code:"",name:"",type:"Asset",group:"Current Assets",parent:"Current Assets",opening:"0",side:"Debit",scope:"All branches"});};
 const exportCsv=()=>{const data=[["Code","Ledger","Type","Group","Parent","Opening balance","Balance nature","Scope"],...shown.map(x=>[x.code,x.name,x.type,x.group,x.parent,String(x.opening),x.side,x.scope])];const csv=data.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(",")).join("\n");const u=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));const a=document.createElement("a");a.href=u;a.download="poultryone-chart-of-accounts.csv";a.click();URL.revokeObjectURL(u);};
 return <div className="module-page coa-page">
 <div className="page-heading"><div><div className="eyebrow">ACCOUNTING FOUNDATION · {branch.toUpperCase()}</div><h1>Chart of Accounts</h1><p>Standard financial accounting groups connected to poultry-specific operations.</p></div><div className="heading-actions"><button className="btn-secondary" onClick={exportCsv}><Download size={16}/> Export CSV</button><button className="btn-primary" onClick={()=>{setNotice("");setModal(true);}}><Plus size={17}/> Create ledger</button></div></div>
 <div className="demo-banner"><div className="demo-icon"><AlertCircle size={17}/></div><div><b>Prototype accounting structure</b><span>Hybrid chart with illustrative sample balances. No live posting, database or permanent storage.</span></div><span className="demo-tag">DEMO DATA</span></div>
 <div className="coa-summary-grid">{["Asset","Liability","Equity","Income","Expense"].map((t,i)=><div className="coa-summary-card" key={t}><div className="coa-summary-top"><span>{t} accounts</span><span className={`coa-type-icon mark-${i}`}>{t[0]}</span></div><b>{count(t)}</b><small>{coaMoney(total(t))} opening balance</small></div>)}</div>
 <div className="coa-info-grid"><div className="panel coa-structure"><div className="panel-header"><div><h2>Hybrid account structure</h2><p>Financial groups and poultry-specific sub-groups</p></div><span className="coa-pill">5 account types</span></div><div className="coa-tree-grid">
 {[
 ["ASSETS","Current assets","Cash & bank · Feed / medicine inventory · Farmer advances",0],
 ["LIABILITIES","Current liabilities","Feed creditors · Medicine creditors · Farmer settlements payable",1],
 ["EQUITY","Capital & reserves","Owner capital · Retained earnings",2],
 ["INCOME","Operating revenue","Live bird sales · By-product sales · Other income",3],
 ["EXPENSES","Production & operating costs","Chicks · Feed · Medicines · Growing charges · Logistics",4]
 ].map(g=><div className="coa-tree-item" key={g[0] as string}><div className={`coa-tree-mark mark-${g[3]}`}>{(g[0] as string)[0]}</div><div><b>{g[0]}</b><strong>{g[1]}</strong><span>{g[2]}</span></div><span className="coa-tree-count">{count(["Asset","Liability","Equity","Income","Expense"][g[3] as number])}</span></div>)}
 </div></div><div className="panel coa-rules"><div className="panel-header"><div><h2>Accounting rules</h2><p>Normal balance classification</p></div></div><div className="rule-row"><i className="rule-dot debit-dot"/><div><b>Debit balance</b><small>Assets and expenses normally carry debit balances.</small></div></div><div className="rule-row"><i className="rule-dot credit-dot"/><div><b>Credit balance</b><small>Liabilities, equity and income normally carry credit balances.</small></div></div><div className="coa-note"><AlertCircle size={15}/><span>Before go-live, opening debit and credit balances must reconcile. These sample balances are illustrative, not a reconciled trial balance.</span></div></div></div>
 <div className="panel coa-register"><div className="coa-register-head"><div><h2>Ledger register</h2><p>{shown.length} shown · {ledgers.length} ledgers in demo</p></div><div className="coa-filters"><div className="table-search"><Search size={15}/><input placeholder="Search code, ledger or group..." value={query} onChange={e=>setQuery(e.target.value)}/></div><select value={scope} onChange={e=>setScope(e.target.value)}><option value="All">All branch scopes</option><option>All branches</option><option>Head Office</option><option>Giridih</option><option>Ranchi</option><option>Patna</option><option>Dhanbad</option></select></div></div>
 <div className="coa-type-tabs">{types.map(t=><button key={t} className={filter===t?"selected":""} onClick={()=>setFilter(t)}>{t}<span>{t==="All"?ledgers.length:count(t)}</span></button>)}</div>
 <div className="table-scroll"><table className="data-table coa-table"><thead><tr><th>Account code</th><th>Ledger name</th><th>Account group</th><th>Type</th><th>Opening balance</th><th>Balance nature</th><th>Branch scope</th><th>Status</th></tr></thead><tbody>{shown.map(x=><tr key={x.code}><td className="coa-code">{x.code}</td><td><b className="table-primary">{x.name}</b><small className="coa-parent">{x.parent}</small></td><td>{x.group}</td><td><span className={`coa-type-tag type-${x.type.toLowerCase()}`}>{x.type}</span></td><td className="coa-amount">{coaMoney(x.opening)}</td><td><span className={`balance-nature ${x.side.toLowerCase()}`}>{x.side}</span></td><td>{x.scope}</td><td><span className="status status-good"><i/>Active</span></td></tr>)}</tbody></table>{!shown.length&&<div className="empty-state"><Search size={22}/><b>No ledgers found</b><span>Change your search or filters.</span></div>}</div><div className="table-pagination"><span>Showing {shown.length} of {ledgers.length} demo ledgers</span><span>Temporary session data</span></div></div>
 <div className="module-bottom-grid"><div className="panel helper-panel"><div className="helper-icon"><BookOpen size={18}/></div><div><h3>Next accounting dependency</h3><p>Voucher entry will use these ledgers and validate that total debits equal total credits before posting.</p></div></div><div className="panel helper-panel"><div className="helper-icon"><ShieldCheck size={18}/></div><div><h3>Control design</h3><p>Unique account codes, controlled account groups and role-based changes will be enforced in the backend phase.</p></div></div></div>
 {notice&&<div className="inline-notice"><Check size={16}/>{notice}<button onClick={()=>setNotice("")}><X size={14}/></button></div>}
 {modal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(false);}}><div className="entry-modal coa-modal"><div className="modal-header"><div><div className="eyebrow">NEW LEDGER · CHART OF ACCOUNTS</div><h2>Create ledger account</h2><p>Define account identity, classification and opening balance.</p></div><button className="icon-button" onClick={()=>setModal(false)}><X size={18}/></button></div><div className="modal-fields">
 <label>Account code *<input placeholder="e.g. 5103" value={form.code} onChange={e=>setForm({...form,code:e.target.value})}/></label><label>Ledger name *<input placeholder="e.g. Farm electricity expense" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label>
 <label>Account type<select value={form.type} onChange={e=>setForm({...form,type:e.target.value,group:e.target.value==="Asset"?"Current Assets":e.target.value==="Liability"?"Current Liabilities":e.target.value==="Equity"?"Capital Account":e.target.value==="Income"?"Operating Revenue":"Direct Production Costs"})}>{["Asset","Liability","Equity","Income","Expense"].map(t=><option key={t}>{t}</option>)}</select></label>
 <label>Account group<select value={form.group} onChange={e=>setForm({...form,group:e.target.value})}>{(form.type==="Asset"?["Current Assets","Cash & Cash Equivalents","Bank Accounts","Inventory","Loans & Advances","Fixed Assets"]:form.type==="Liability"?["Current Liabilities","Trade Payables","Other Current Liabilities","Long-term Liabilities"]:form.type==="Equity"?["Capital Account","Reserves & Surplus"]:form.type==="Income"?["Operating Revenue","Other Income"]:["Direct Production Costs","Selling & Distribution","Administrative Expenses","Finance Costs"]).map(g=><option key={g}>{g}</option>)}</select></label>
 <label>Parent group<input placeholder="e.g. Current Assets" value={form.parent} onChange={e=>setForm({...form,parent:e.target.value})}/></label><label>Branch scope<select value={form.scope} onChange={e=>setForm({...form,scope:e.target.value})}>{["All branches","Head Office","Giridih","Ranchi","Patna","Dhanbad"].map(x=><option key={x}>{x}</option>)}</select></label>
 <label>Opening balance (₹)<input type="number" min="0" value={form.opening} onChange={e=>setForm({...form,opening:e.target.value})}/></label><label>Balance nature<select value={form.side} onChange={e=>setForm({...form,side:e.target.value})}><option>Debit</option><option>Credit</option></select></label>
 </div><div className="modal-footer"><span>* Required · Demo only</span><button className="btn-secondary" onClick={()=>setModal(false)}>Cancel</button><button className="btn-primary" onClick={save}><Check size={16}/> Save ledger</button></div></div></div>}
 <footer className="page-footer"><span>© 2026 PoultryOne ERP · Accounts module prototype</span><span><i/> Sample environment</span></footer></div>;
}

function ModuleWorkspace({active,branch}:{active:string;branch:string}) {
  const config=moduleConfigs[active];
  const [query,setQuery]=useState(""); const [tab,setTab]=useState(config?.tabs?.[0]||"All records");
  const [modal,setModal]=useState(false); const [form,setForm]=useState<Record<string,string>>({});
  const [rows,setRows]=useState(config?.rows||[]);
  const [notice,setNotice]=useState("");
  if(active==="Chart of accounts") return <ChartOfAccountsWorkspace branch={branch}/>;
  if(!config) return <div className="placeholder-page"><div className="placeholder-card"><div className="placeholder-icon"><Settings size={27}/></div><h1>{active}</h1><p>This screen is planned for a later prototype milestone.</p></div></div>;
  const filtered=rows.filter(row=>row.join(" ").toLowerCase().includes(query.toLowerCase()));
  const isAccounts=["Chart of accounts","Vouchers","Ledgers","Payments & receipts","Farmer settlements"].includes(active);
  const onSave=()=>{const values=config.columns.map((_,i)=>form[config.fields[i]]||"—");const next=config.columns.map((col,i)=>{if(i===0)return form[config.fields[0]]||`NEW-${String(rows.length+1).padStart(3,"0")}`;return values[i]||"—";});setRows([next,...rows]);setModal(false);setForm({});setNotice("Demo record added to this screen. It will reset when the page is refreshed.");};
  return <div className="module-page">
    <div className="page-heading"><div><div className="eyebrow">{config.subtitle.toUpperCase()} · {branch.toUpperCase()}</div><h1>{active}</h1><p>{config.description}</p></div><div className="heading-actions"><button className="btn-secondary" onClick={()=>window.print()}><Download size={16}/> Export</button><button className="btn-primary" onClick={()=>{setNotice("");setModal(true);}}><Plus size={17}/>{config.primary}</button></div></div>
    <div className="demo-banner"><div className="demo-icon"><AlertCircle size={17}/></div><div><b>Prototype data only</b><span>These are sample records. Additions and actions are temporary and are not saved to a database.</span></div><span className="demo-tag">DEMO</span></div>
    <div className="module-kpis">{config.kpis.map(([label,value,note])=><div className="module-kpi" key={label}><span>{label}</span><b>{value}</b>{note&&<small>{note}</small>}</div>)}</div>
    <div className="panel module-table-panel">
      <div className="module-toolbar"><div><h2>{active} register</h2><p>{filtered.length} records shown · Illustrative data</p></div><div className="toolbar-actions"><div className="table-search"><Search size={15}/><input placeholder={`Search ${active.toLowerCase()}...`} value={query} onChange={e=>setQuery(e.target.value)}/></div><button className="btn-secondary compact" onClick={()=>{setQuery("");setNotice("Filters cleared.");}}><RotateCcw size={15}/> Reset</button><button className="btn-secondary compact" onClick={()=>window.print()}><FileSpreadsheet size={15}/> Export</button></div></div>
      {active==="Vouchers"&&<div className="module-tabs">{["All records","Payment","Receipt","Journal","Contra"].map(t=><button className={tab===t?"selected":""} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div>}
      <div className="table-scroll"><table className="data-table"><thead><tr>{config.columns.map(c=><th key={c}>{c}</th>)}<th>Action</th></tr></thead><tbody>{filtered.map((row,i)=><tr key={`${row[0]}-${i}`}>{config.columns.map((c,j)=><td key={c}>{j===config.columns.length-1&&["Status"].includes(c)?<span className={`status ${/active|approved|posted|completed|healthy|good|dispatched|in stock/i.test(row[j])?"status-good":/pending|low|review|near expiry|attention|setup/i.test(row[j])?"status-warning":"status-pending"}`}><i/>{row[j]}</span>:<span className={j===0?"table-primary":""}>{row[j]||"—"}</span>}</td>)}<td><button className="row-action" onClick={()=>setNotice(`Opened ${row[0]} in demo preview. Detailed record view will be added in the next iteration.`)}>View <ArrowUpRight size={13}/></button></td></tr>)}</tbody></table>{filtered.length===0&&<div className="empty-state"><Search size={22}/><b>No matching records</b><span>Try another search term.</span></div>}</div>
      <div className="table-pagination"><span>Showing {filtered.length} of {rows.length} sample records</span><span>Page 1 of 1 <button disabled>Previous</button><button disabled>Next</button></span></div>
    </div>
    {notice&&<div className="inline-notice"><Check size={16}/>{notice}<button onClick={()=>setNotice("")}><X size={14}/></button></div>}
    <div className="module-bottom-grid"><div className="panel helper-panel"><div className="helper-icon"><ClipboardCheck size={18}/></div><div><h3>Workflow guidance</h3><p>{isAccounts?"Use approved vouchers and mapped ledgers to maintain an auditable double-entry accounting trail.":"Keep every operational record linked to its branch, farmer and batch wherever applicable."}</p></div></div><div className="panel helper-panel"><div className="helper-icon"><ShieldCheck size={18}/></div><div><h3>Control reminder</h3><p>In the final system, role permissions, maker-checker approvals and audit history will control sensitive changes.</p></div></div></div>
    {modal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(false);}}><div className="entry-modal"><div className="modal-header"><div><div className="eyebrow">POULTRYONE ERP · DEMO ENTRY</div><h2>{config.primary}</h2><p>Complete the fields below to add a temporary sample row.</p></div><button className="icon-button" onClick={()=>setModal(false)}><X size={18}/></button></div><div className="modal-fields">{config.fields.map((field,i)=><label key={field}>{field}{/date|expiry/i.test(field)?<input type="date" value={form[field]||""} onChange={e=>setForm({...form,[field]:e.target.value})}/>:/type|branch|status|mode|nature|category|format|decision/i.test(field)?<select value={form[field]||""} onChange={e=>setForm({...form,[field]:e.target.value})}><option value="">Select {field.toLowerCase()}</option>{(field.toLowerCase().includes("branch")?["Giridih","Ranchi","Patna","Dhanbad"]:field.toLowerCase().includes("type")?["Payment","Receipt","Journal","Contra","Purchase","Stock issue","Stock receipt"]:["General","Active","Pending","Approved","Debit","Credit"]).map(v=><option key={v}>{v}</option>)}</select>:<input placeholder={`Enter ${field.toLowerCase()}`} value={form[field]||""} onChange={e=>setForm({...form,[field]:e.target.value})}/>}</label>)}</div><div className="modal-footer"><span>Demo only · No database connection</span><button className="btn-secondary" onClick={()=>setModal(false)}>Cancel</button><button className="btn-primary" onClick={onSave}><Check size={16}/> Save demo entry</button></div></div></div>}
    <footer className="page-footer"><span>© 2026 PoultryOne ERP · Prototype v0.2</span><span><i/> Sample environment</span></footer>
  </div>;
}
